 14 |      d  id                                 like(arid)
 15 | 
 16 |      D indds           ds
 17 |      D  help                   1      1n
 18 |      D  exit                   3      3n
 19 |      D  prompt                 4      4n
 20 |      D  refresh                5      5n
 21 |      D  Create                 6      6n
 22 |      D  cancel                12     12n
 23 |      D  morekeys              24     24n
 24 |      D  pagedown              25     25n
 25 |      D  sflclr                30     30n
 26 |      D  sfldsp                31     31n
 27 |      D  sfldspctl             32     32n
 28 |      D  sflnxtchg             33     33n
 29 |      D  dspatr_ri             34     34n
 30 |      D  sflmsg                35     35n
 31 |      D  errFamilly            40     40n
 32 |      D  errDesc               41     41n
 33 |      D  sflend                80     80n
 34 | 
 35 |      D info            ds
 36 |      D  lrrn                 378    379i 0
 37 | 
 38 |      D rrn01           s              5i 0
 39 |      D rrs01           s              5i 0
 40 |      D err01           s               n
 41 | 
 42 |      D panel           S              3i 0 INZ(1)
 43 |      D step01          S              3    inz(prp)
 44 |      D step02          S              3    inz(prp)
 45 |      D step03          S              3    inz(prp)
 46 |      d savId           s                   like(arid)
 47 |      d savDesc         s                   like(ardesc)
 48 |      d NewId           s              6  0
 49 |      d User            s             10    inz(*user)
 50 |      d count           s              3i 0
 51 |      d mode            s              3
 52 | 
 53 |      d crt             c                   'CRT'
 54 |      d upd             c                   'UPD'
 55 |      d prp             c                   'prp'
 56 |      d lod             c                   'lod'
 57 |      d dsp             c                   'dsp'
 58 |      d key             c                   'key'
 59 |      d chk             c                   'chk'
 60 |      d act             c                   'act'
 61 |       /free
 62 | 
 63 |        select;
 64 |        when panel = 1;
 65 |          exsr pnl01;
 66 |        when panel = 2;
 67 |          exsr pnl02;
 68 |        when panel = 3;
 69 |          exsr pnl03;
 70 |        other;
 71 |          exsr pnl00;
 72 |        endsl;
 73 |        //- Subfiles  01 Subroutines --------------------------------------  ---
 74 |        begsr pnl01;
 75 |          select ;
 76 |          when step01 = prp ;
 77 |            exsr s01prp;
 78 |          when step01 = lod ;
 79 |            exsr s01lod;
 80 |          when step01 = dsp ;
 81 |            exsr s01dsp;
 82 |          when step01 = key ;
 83 |            exsr s01key;
 84 |          when step01 = chk ;
 85 |            exsr s01chk;
 86 |          when step01 = act ;
 87 |            exsr s01act ;
 88 |          endsl;
 89 |        endsr;
 90 |        //--- Clear Subfile  ----------------------------------------------------
 91 |        begsr s01prp;
 92 |          RRn01 = 0;
 93 |          sflclr = *on;
 94 |          write ctl01;
 95 |          sflclr = *off;
 96 |          step01 = lod;
 97 |          clear savid;
 98 |          savDesc = posTo;
 99 |          clear posTo;
100 |          rrs01 = 0;
101 |        endsr;
102 |        //--- Load Subfile  -----------------------------------------------------
103 |        begsr s01lod;
104 |          exsr s01rst;
105 |          RRb01 = RRn01 + 1;
106 |          opt01 = 0;
107 |          count = 0;
108 |          read article2;
109 |          dow not %eof(article2) and count < 14;
110 |            RRN01 += 1;
111 |            count += 1;
112 |            write sfl01;
113 |            read article2;
114 |          enddo;
115 |          sflend = %eof(article1);
116 |          step01 = dsp;
117 |          exsr s01sav;
118 |        endsr;
119 |        //--- restore last read -------------------------------------------------
120 |        begsr s01rst;
121 |          setll (savdesc:savid)  article2;
122 |          rrn01 = rrs01;
123 |        endsr;
124 |        //--- Save last read -------------------------------------------------
125 |        begsr s01sav;
126 |          savid = arid;
127 |          savdesc = ardesc;
128 |          rrs01 = rrn01;
129 |        endsr;
130 |        //--- Display Subfile  --------------------------------------------------
131 |        begsr s01dsp;
132 |          sfldspctl = *on;
133 |          sfldsp = RRn01 > 0;
134 | 
135 |          write key01;
136 |          exfmt ctl01;
137 |          if LRRN <>0;
138 |            RRb01 = LRRN;
139 |          endif;
140 |          step01 = key;
141 |        endsr;
142 |        //--- Command Keys  -----------------------------------------------------
143 |        begsr s01key;
144 |          select;
145 |          when exit;
146 |            panel  = 0;
147 |            step01 = prp;
148 |          when cancel;
149 |            step01 = prp;
150 |            panel  = panel  - 1;
151 |          when create;
152 |            step01 = prp;
153 |            panel  = 2 ;
154 |            step02 = prp;
155 |            mode = crt;
156 |          when pagedown;
157 |            step01 = lod;
158 |          other;
159 |            step01 = chk;
160 |          endsl;
161 |        endsr;
162 |        //--- Check Subfile  ----------------------------------------------------
163 |        begsr s01chk;
164 |          step01 = act;
165 |          err01 = *off;
166 |          sflnxtchg = *on;
167 |          readc(e) sfl01;
168 |          dow not %error and not %eof;
169 |            if opt01  > 6 or opt01 = 1 or opt01 = 5;
170 |              step01 = dsp;
171 |              dspatr_ri = *on;
172 |              sflmsg = *on;
173 |              if not err01;
174 |                rrb01 = rrn01;
175 |                err01 = *on;
176 |              endif;
177 |            endif;
178 |            update sfl01;
179 |            dspatr_ri = *off;
180 |            readc(e) sfl01;
181 |          enddo;
182 |          sflnxtchg = *off;
183 |        endsr;
184 |        //--- action Subfile  ---------------------------------------------------
185 |        begsr s01act;
186 |          readc(e) sfl01;
187 |          select;
188 |          when %error or %eof;
189 |            if posto > ' ';
190 |              step01 = prp;
191 |            else;
192 |              step01 = dsp;
193 |            endif;
194 |          when opt01 = 2;
195 |            panel = 2;
196 |            step02 = prp;
197 |            opt01 = 0;
198 |            update sfl01;
199 |            mode = upd;
200 |          when opt01 = 3;
201 |            panel = 3;
202 |            step02 = prp;
203 |            opt01 = 0;
204 |            update sfl01;
205 |          when opt01 = 4;
206 |            chain arid article1;
207 |            ardel = 'X';
208 |            armod = %timestamp();
209 |            armodid = user;
210 |            update farti;
211 |            step02 = dsp;
212 |            opt01 = 0;
213 |            update sfl01;
214 |          when opt01 = 6;
215 |            providers(arid);
216 |            opt01 = 0;
217 |            update sfl01;
218 |          other;
219 | 
220 |          endsl;
221 |        endsr;
222 | 
223 | 
224 |        //--- Format 02 Subroutines ------------------------------------     ---
225 |        begsr pnl02;
226 |          select ;
227 |          when step02 = prp ;
228 |            exsr s02prp;
229 |          when step02 = dsp ;
230 |            exsr s02dsp;
231 |          when step02 = key ;
232 |            exsr s02key;
233 |          when step02 = chk ;
234 |            exsr s02chk;
235 |          when step02 = act ;
236 |            exsr s02act ;
237 |          endsl;
238 | 
239 |        endsr;
240 |        //--- clear & Load ------------------------------------------------------
241 |        begsr S02prp;
242 |          if mode = crt;
243 |            setgt *hival article1;
244 |            readp article1;
245 |            Newid = %dec(arid :6: 0)  +1;
246 |            reset farti;
247 |            arid = %editc(NewId:'X');
248 |          else;
249 |            chain arid article1;
250 |            famdesc = getArtFamDesc(artifa);
251 |          endif;
252 |          step02 = dsp;
253 |        endsr;
254 |        //--- Display  ----------------------------------------------------------
255 |        begsr S02dsp;
256 |          exfmt fmt02;
257 |          step02 = key;
258 |        endsr;
259 |        //--- command Keys  -----------------------------------------------------
260 |        begsr S02key;
261 |          select;
262 |          when exit;
263 |            panel  = 1;
264 |            step02 = prp;
265 |          when cancel;
266 |            step02 = prp;
267 |            panel  = panel  - 1;
268 |          when prompt;
269 |            artifa = sltArtFam(artifa);
270 |            famdesc = getArtFamDesc(artifa);
271 |            step02 = dsp;
272 |          other;
273 |            step02 = chk;
274 |          endsl;
275 |        endsr;
276 |        //--- check -------------------------------------------------------------
277 |        begsr S02chk;
278 |          step02 = act;
279 |          if ardesc = ' ';
280 |            errDesc = *on;
281 |            step02 = dsp;
282 |          endif;
283 |          if not existArtFam(artifa);
284 |            errFamilly = *on;
285 |            step02 = dsp;
286 |          endif;
287 | 
288 |        endsr;
289 |        //--- Action ------------------------------------------------------------
290 |        begsr S02act;
291 |          step02 = prp;
292 |          armod = %timestamp();
293 |          armodid = user;
294 |          if mode = upd;
295 |            update farti;
296 |          else;
297 |            arcrea = %date();
298 |            write(e) farti;
299 |            dow %error;
300 |              Newid += 1;
301 |              arid = %editc(NewId:'X');
302 |              write(e) farti;
303 |            enddo;
304 |            savdesc = ardesc;
305 |            savId = arid;
306 |            step01 = lod;
307 |          endif;
308 |          panel = 1;
309 |        endsr;
310 | 
311 |        //--- Format 03 Subroutines ------------------------------------     ---
312 |        begsr pnl03;
313 |          select ;
314 |          when step03 = prp ;
315 |            exsr s03prp;
316 |          when step03 = dsp ;
317 |            exsr s03dsp;
318 |          when step03 = key ;
319 |            exsr s03key;
320 |          when step03 = chk ;
321 |            exsr s03chk;
322 |          when step03 = act ;
323 |            exsr s03act ;
324 |          endsl;
325 | 
326 |        endsr;
327 |        //--- clear & Load ------------------------------------------------------
328 |        begsr S03prp;
329 |          exec sql set option commit = *none;
330 |          exec sql select ARTICLE_INFORMATION into :text
331 |                   FROM artiinf
332 |                   WHERE ARTICLE_INFO_ID = :arid;
333 |          if sqlcod <> 0;
334 |            mode = crt;
335 |            clear text;
336 |          else;
337 |            mode = upd;
338 |          endif;
339 |          step03 = dsp;
340 |        endsr;
341 |        //--- Display  ----------------------------------------------------------
342 |        begsr S03dsp;
343 |          exfmt fmt03;
344 |          step03 = key;
345 |        endsr;
346 |        //--- command Keys  -----------------------------------------------------
347 |        begsr S03key;
348 |          select;
349 |          when exit;
350 |            panel  = 1;
351 |            step03 = prp;
352 |          when cancel;
353 |            step03 = prp;
354 |            panel  = 1;
355 |          other;
356 |            step03 = chk;
357 |          endsl;
358 |        endsr;
359 |        //--- check -------------------------------------------------------------
360 |        begsr S03chk;
361 |          step03 = act;
362 |        endsr;
363 |        //--- Action ------------------------------------------------------------
364 |        begsr S03act;
365 |          step03 = prp;
366 |          panel = 1;
367 |          if mode = upd;
368 |            exec sql update artiinf
369 |                   set ARTICLE_INFORMATION = trim(:text)
370 |                   WHERE ARTICLE_INFO_ID = :arid;
371 |          else;
372 |            exec sql insert into artiinf
373 |                     Values(:arid, trim(:text));
374 |          endif;
375 |        endsr;
376 |        //--------INITIALIZATION ----------------------------------
377 |        begsr *inzsr;
378 |        endsr;
379 |        //--------END SUBROUTINE ----------------------------------
380 |        begsr pnl00;
381 |          *inlr = *on;
382 |        endsr;
383 |       /end-free
